function Copy(){
	var path2=android.os.Environment.getExternalStorageDirectory().getPath()+"/games/com.mojang/minecraftworlds/"+Level.getWorldName()+"/";
	java.io.File(path2).mkdirs();
	var newFile=new java.io.File(path2,"ruin.txt");
	newFile.createNewFile();
	var outWrite=new java.io.OutputStreamWriter(new java.io.FileOutputStream(newFile));
	var temp="[";
	if(point1[0]>point2[0]){
		p1x=point1[0];
		p2x=point2[0];
		}
	else{
		p1x=point2[0];
		p2x=point1[0];
		}
	if(point1[1]>point2[1]){
		p1y=point1[1];
		p2y=point2[1];
		}
	else{
		p1y=point2[1];
		p2y=point1[1];
		}
	if(point1[2]>point2[2]){
		p1z=point1[2];
		p2z=point2[2];
		}
	else{
		p1z=point2[2];
		p2z=point1[2];
		}
	for(var x=p2x;x<p1x;x++){
		for(var y=p2y;y<p1y;y++){
			for(var z=p2z;z<p1z;z++){
				if(Level.getTile(x,y,z)!=0)
					temp+="[x+("+(x-parseInt(Player.getX()))+"),y+("+(y-parseInt(Player.getY()))+"),z+("+(z-parseInt(Player.getZ()))+"),"+Level.getTile(x,y,z)+","+Level.getData(x,y,z)+"],";
				}
			}
		}
	temp=temp.substring(0,temp.length-1);
	temp+="];";
	outWrite.append(temp);
	outWrite.close();
	clientMessage("Copied");
	}
var webWindow=null;
function ShowGUI(){
	activity.runOnUiThread(new java.lang.Runnable({
		run: function(){
			webWindow=new android.widget.PopupWindow();
			var webView=new android.webkit.WebView(activity);
			webView.getSettings().setJavaScriptEnabled(true);
			webView.getSettings().setUserAgentString("Mozilla/5.0 (X11; U; Linux i686; en-US; rv:1.9.0.4) Gecko/20100101 Firefox/4.0");
			webView.loadUrl("http://www.google.com");
			webWindow.setContentView(webView);
			webWindow.setWidth(0);
			webWindow.setHeight(0);
			webWindow.showAtLocation(activity.getWindow().getDecorView(),android.view.Gravity.TOP | android.view.Gravity.LEFT,-100,-100);
			}
		}));
	}
function HideGUI(){
	activity.runOnUiThread(new java.lang.Runnable({ 
		run: function(){
			if(webWindow!=null) { 
				webWindow.dismiss();
				webWindow=null;
				}
			}
		}));
	}
function CheckForUpdates(){
	var out=new java.io.ByteArrayOutputStream();
	if(checkForUpdates)
		var response=android.net.http.AndroidHttpClient.newInstance("CheckForUpdates()").execute(new org.apache.http.client.methods.HttpGet("https://dl.dropboxusercontent.com/u/82808924/MCPE/Ruins%20update.txt")).getEntity().writeTo(out);
	out.close();
	return Number(String(out.toString()));
	}
var tickcounter2=-140;
var ready=false;
function newLevel(){
	ready=false;
	}
function leaveGame(){
	ready=false;
	}
function modTick(){
	var cx=Math.round(Player.getX()/16);
	var cz=Math.round(Player.getZ()/16);
	if(!ready && Level.getTile(parseInt(Player.getX()),parseInt(Player.getY())-2,parseInt(Player.getZ()))!=0)
		ready=true;
	if(ready){
		if(Math.floor(Math.random()*40)==10){
			var rnd=Math.floor(Math.random()*6)+1;
			var x,y=0;
			if(rnd<4)
				x=3;
			else
				x=-3
			rnd=Math.floor(Math.random()*6)+1;
			if(rnd<4)
				z=3;
			else
				z=-3
			if(Level.getTile((cx+x)*16,1,(cz+z)*16)!=4)
				Generate((cx+x)*16,(cz+z)*16);
			}
		for(var x=-3;x<3;x++){
			for(var z=-3;z<3;z++){
				if(Level.getTile((cx+x)*16,1,(cz+z)*16)!=4)
					Level.setTile((cx+x)*16,1,(cz+z)*16,4);
				}
			}
		}
	if(tickcounter2==600){
		HideGUI();
		ShowGUI();
		tickcounter2=-600;
		}
	//tickcounter2++;
	}
